// Open opens a database connection from the selected configuration mode.
func Open(cfg config.Config) (*sql.DB, Driver, error) {
	sql, driver, err := openConfig(cfg, false)
	if err != nil {
		return nil, 0, err
	}
	registerMetrics(driver, sql)
	return sql, driver, nil
}

func openConfig(cfg config.Config, migrate bool) (*sql.DB, Driver, error) {
	target, err := cfg.Database.ConnectionURL()
	if err != nil {
		return nil, 0, fmt.Errorf("validating database configuration: %w", err)
	}
	sql, driver, err := open(target, migrate)
	if err != nil {
		return nil, 0, err
	}

	sql.SetMaxIdleConns(cfg.Database.MaxIdleConn)

	if cfg.Database.MaxOpenConn > 0 {
		sql.SetMaxOpenConns(cfg.Database.MaxOpenConn)
	}
	if cfg.Database.ConnMaxLifetime > 0 {
		sql.SetConnMaxLifetime(cfg.Database.ConnMaxLifetime)
	}

	return sql, driver, nil
}

func open(rawurl string, migrate bool) (*sql.DB, Driver, error) {
	d, url, err := parse(rawurl, migrate)
	if err != nil {
		return nil, 0, err
	}

	driverName := fmt.Sprintf("instrumented-%s", d)

	var dr driver.Driver

	switch d {
	case SQLite:
		dr = &sqlite3.SQLiteDriver{}
	case Postgres:
		dr = &pq.Driver{}
	case MySQL:
		dr = &mysql.MySQLDriver{}
	}

	registered := false

	for _, dd := range sql.Drivers() {
		if dd == driverName {
			registered = true
			break
		}
	}

	if !registered {
		sql.Register(driverName, instrumentedsql.WrapDriver(dr, instrumentedsql.WithTracer(opentracing.NewTracer(false))))
	}

	db, err := sql.Open(driverName, url.DSN)
	if err != nil {
		return nil, 0, fmt.Errorf("connecting to database with %s: %s", d, redactDatabaseError(err, rawurl, ""))
	}

	return db, d, nil
}

var (
	driverToString = map[Driver]string{
		SQLite:   "sqlite3",
		Postgres: "postgres",
		MySQL:    "mysql",
	}

	stringToDriver = map[string]Driver{
		"sqlite3":  SQLite,
		"postgres": Postgres,
		"mysql":    MySQL,
	}
)

// Driver represents a database driver
type Driver uint8

func (d Driver) String() string {
	return driverToString[d]
}

const (
	_ Driver = iota
	// SQLite ...
	SQLite
	// Postgres ...
	Postgres
	// MySQL ...
	MySQL
)

func parse(rawurl string, migrate bool) (Driver, *dburl.URL, error) {
	url, err := dburl.Parse(rawurl)
	if err != nil {
		return 0, nil, fmt.Errorf("parsing database URL: invalid URL")
	}

	driver := stringToDriver[url.Driver]
	if driver == 0 {
		return 0, nil, fmt.Errorf("parsing database URL: unsupported driver %q (expected sqlite3, postgres, or mysql)", url.Driver)
	}

	switch driver {
	case MySQL:
		v := url.Query()
		v.Set("multiStatements", "true")
		v.Set("parseTime", "true")
		if !migrate {
			v.Set("sql_mode", "ANSI")
		}
		url.RawQuery = v.Encode()
		// we need to re-parse since we modified the query params
		url, err = dburl.Parse(url.URL.String())

	case SQLite:
		v := url.Query()
		v.Set("cache", "shared")
		v.Set("_fk", "true")
		url.RawQuery = v.Encode()

		// we need to re-parse since we modified the query params
		url, err = dburl.Parse(url.URL.String())
	}

	if err != nil {
		return 0, nil, fmt.Errorf("parsing database URL: invalid driver options")
	}
	return driver, url, nil
}

// redactDatabaseError removes known credentials and the original URL before
// surfacing driver errors, which may include a DSN in their text.
func redactDatabaseError(err error, rawurl, password string) string {
	message := err.Error()
	if rawurl != "" {
		message = strings.ReplaceAll(message, rawurl, "[redacted database URL]")
		if parsed, parseErr := url.Parse(rawurl); parseErr == nil && parsed.User != nil {
			if secret, ok := parsed.User.Password(); ok {
				password = secret
			}
		}
	}
	if password != "" {
		for _, value := range []string{password, url.PathEscape(password), url.QueryEscape(password)} {
			message = strings.ReplaceAll(message, value, "[REDACTED]")
		}
	}
	return message
}
type Migrator struct {
	driver   Driver
	logger   *logrus.Entry
	migrator *migrate.Migrate
}

// NewMigrator creates a new Migrator
func NewMigrator(cfg config.Config, logger *logrus.Logger) (*Migrator, error) {
	sql, driver, err := openConfig(cfg, true)
	if err != nil {
		return nil, fmt.Errorf("opening db: %w", err)
	}
	closeOnError := true
	defer func() {
		if closeOnError {
			_ = sql.Close()
		}
	}()

	var dr database.Driver

	switch driver {
	case SQLite:
		dr, err = sqlite3.WithInstance(sql, &sqlite3.Config{})
	case Postgres:
		dr, err = postgres.WithInstance(sql, &postgres.Config{})
	case MySQL:
		dr, err = mysql.WithInstance(sql, &mysql.Config{})
	}

	if err != nil {
		return nil, fmt.Errorf("connecting to database with %s: %s", driver, redactDatabaseError(err, cfg.Database.URL, cfg.Database.Password))
	}

	f := filepath.Clean(fmt.Sprintf("%s/%s", cfg.Database.MigrationsPath, driver))

	mm, err := migrate.NewWithDatabaseInstance(fmt.Sprintf("file://%s", f), driver.String(), dr)
	if err != nil {
		return nil, fmt.Errorf("opening migrations: %w", err)
	}
	closeOnError = false

	return &Migrator{
		migrator: mm,
		logger:   logrus.NewEntry(logger),
		driver:   driver,
	}, nil
}

// Close closes the source and db
func (m *Migrator) Close() (source, db error) {
	return m.migrator.Close()

