func Default() *Config {
	return &Config{
		Log: LogConfig{
			Level: "INFO",
		},

	dbName            = "db.name"
	dbMigrationsPath  = "db.migrations.path"
	dbMaxIdleConn     = "db.max_idle_conn"
	dbMaxOpenConn     = "db.max_open_conn"
	dbConnMaxLifetime = "db.conn_max_lifetime"

	// Meta
	metaCheckForUpdates = "meta.check_for_updates"
)

func Load(path string) (*Config, error) {
	v := viper.New()
	v.SetEnvPrefix("FLIPT")
	v.SetEnvKeyReplacer(strings.NewReplacer(".", "_"))
	v.AutomaticEnv()

	v.SetConfigFile(path)

	if err := v.ReadInConfig(); err != nil {
		return nil, fmt.Errorf("loading configuration: %w", err)
	}

	cfg := Default()

	// Logging
	if v.IsSet(logLevel) {
		cfg.Log.Level = v.GetString(logLevel)
	}

	if v.IsSet(logFile) {
		cfg.Log.File = v.GetString(logFile)
		cfg.Database.ConnMaxLifetime = v.GetDuration(dbConnMaxLifetime)
	}

	// Meta
	if v.IsSet(metaCheckForUpdates) {
		cfg.Meta.CheckForUpdates = v.GetBool(metaCheckForUpdates)
	}

	if err := cfg.validate(); err != nil {
		return &Config{}, err
	}

	return cfg, nil
}

func (c *Config) validate() error {
	if c.Server.Protocol == HTTPS {
		if c.Server.CertFile == "" {
			return fmt.Errorf("server.cert_file: required when server.protocol is https")
		}

		if c.Server.CertKey == "" {
			return fmt.Errorf("server.cert_key: required when server.protocol is https")
		}

		if _, err := os.Stat(c.Server.CertFile); err != nil {
			return fmt.Errorf("server.cert_file: cannot access TLS certificate at %q: %w", c.Server.CertFile, err)
		}

		if _, err := os.Stat(c.Server.CertKey); err != nil {
			return fmt.Errorf("server.cert_key: cannot access TLS certificate at %q: %w", c.Server.CertKey, err)
		}
	}
	_, err := c.Database.ConnectionURL()
	return err
}

